struct P { x: i32 }

fn bump(p: lend P): i32 { p.x = p.x + 1; p.x }
fn read(p: view P): i32 { p.x }

fn main(): i32 {
    var value = P { x: 41 };
    _ = bump(lend value);
    _ = read(view value);
    value.x - 42
}

