enum Status {
    Ok = 0,
    Error = 1,
}

fn statusCode(status: Status): i32 {
    when (status) {
        (Status.Ok) 0,
        (_) 1
    }
}

fn main(): i32 {
    statusCode(Status.Ok)
}
